# Schema: phase, work/output, four responsibility cells, list of direct legal provisions, condition/control.
R=[]
def row(phase,work,owner,contractor,consult,other,refs,note):
 R.append([phase,work,owner,contractor,consult,other,refs,note])

row('A','Tiếp nhận nhu cầu và kiểm tra hiện trạng → biên bản hiện trạng, ảnh, danh mục hư hỏng','–','–','P nếu thuê','C: Đơn vị quản lý, sử dụng công trình',[('104','khoản 1 Điều 20')],'Bắt buộc có cơ sở đề xuất; biên bản, ảnh là cách tổ chức hồ sơ nội bộ, không phải mẫu pháp định riêng. Xác định công trình, địa điểm và hồ sơ tài sản hiện có.')
row('A','Phân loại công việc và nguồn kinh phí → phiếu xác định phạm vi áp dụng','–','–','P','C: Đơn vị sử dụng ngân sách; P: cơ quan tài chính',[('NS','Điều 40'),('104','Điều 1; khoản 1 Điều 20')],'Chỉ dùng quy trình này khi thuộc nhiệm vụ được phép chi thường xuyên. Xây mới phải là hạng mục trong dự án đã đầu tư xây dựng. Không dùng mức dưới 3 tỷ để hợp thức hóa công trình mới ngoài phạm vi.')
row('A','Xác định chế độ xây dựng và nhánh kinh phí → bản phân loại nhiệm vụ hoặc dự án','–','–','P','C: Đơn vị quản lý công trình; P: cơ quan xây dựng',[('104','điểm a khoản 2 Điều 21'),('XD','điểm c khoản 1 Điều 17; Điều 23'),('217','khoản 4 Điều 27')],'Nhánh I dưới 500 triệu; nhánh II từ 500 triệu đến dưới 3 tỷ. Nhánh I không tự động miễn BCKTKT: kiểm tra có hình thành dự án hay chỉ là bảo trì được miễn lập dự án. Ghi nhận lý do chọn nhánh.')
row('A','Rà soát tiêu chuẩn, định mức và quyền quản lý tài sản → bảng kiểm điều kiện','–','–','P','C: Đơn vị quản lý công trình; P: cơ quan quản lý tài sản',[('104','khoản 1 Điều 20'),('XD','Điều 7; Điều 18')],'Đối chiếu định mức trụ sở/cơ sở hoạt động sự nghiệp và quy chuẩn chuyên ngành. Cần xác minh: văn bản phân cấp tài sản, đất đai và định mức cụ thể theo loại đơn vị; chưa xác định địa phương.')
row('A','Lập thuyết minh nhiệm vụ và dự kiến chi phí → hồ sơ đề xuất chủ trương','–','–','P nếu thuê','C: Đơn vị quản lý công trình hoặc đơn vị tổng hợp được giao',[('104','khoản 1 Điều 20')],'Nêu tên, địa điểm, mục tiêu, lý do, tiêu chuẩn/định mức, khối lượng dự kiến và chi phí theo nguồn. Phân biệt dự kiến chi phí với dự toán xây dựng chi tiết lập sau.')
row('A','Rà soát hồ sơ đề xuất và khả năng cân đối → hồ sơ rà soát trình duyệt','–','–','–','C: Cơ quan/đơn vị được giao tổng hợp; P: cơ quan tài chính',[('104','điểm c khoản 2 Điều 20')],'Không tự đặt thủ tục thẩm định của Sở Xây dựng ở bước chủ trương. Nội dung rà soát phục vụ người có thẩm quyền quyết định, có thể thực hiện trong quy trình trình duyệt nội bộ.')
row('A','Phê duyệt chủ trương và dự kiến chi phí → quyết định theo Mẫu 02','–','–','–','D: Bộ trưởng/thủ trưởng CQTW hoặc UBND tỉnh, chủ thể được phân cấp',[('104','khoản 2 Điều 20; Mẫu 02 phụ lục')],'Cần xác minh quyết định phân cấp hiện hành của bộ hoặc UBND tỉnh. Không mặc định thủ trưởng đơn vị được duyệt vì kinh phí dưới 3 tỷ. Quyết định này chưa thay thế giao dự toán và phê duyệt BCKTKT.')
row('A','Lập và tổng hợp dự toán ngân sách năm → dự toán kinh phí nhiệm vụ','–','–','–','C: Đơn vị sử dụng ngân sách; P: cơ quan quản lý cấp trên',[('104','khoản 3 Điều 20')],'Đính kèm quyết định chủ trương và dự kiến chi phí; tổng hợp qua đơn vị dự toán cấp I gửi cơ quan tài chính. Thực hiện theo lịch lập ngân sách, không tự đặt hạn nộp chung cho mọi địa phương.')
row('A','Tổng hợp, trình và quyết định dự toán ngân sách → quyết định giao dự toán cấp I','–','–','–','C: Cơ quan tài chính; D: cấp có thẩm quyền giao dự toán',[('104','khoản 1 Điều 21'),('NS','Cần xác minh điều khoản và thẩm quyền ngân sách cụ thể của cấp áp dụng')],'Thực hiện chu trình ngân sách theo cấp ngân sách. Trường hợp phát sinh khách quan/bất khả kháng trong năm, thực hiện điểm đ khoản 1 Điều 21 NĐ 104; không cam kết chi trước khi đủ căn cứ.')
row('A','Điều chỉnh chủ trương khi số phân bổ khác dự kiến → quyết định điều chỉnh','–','–','P nếu cần','C: Đơn vị quản lý; D: cấp đã có thẩm quyền duyệt chủ trương',[('104','điểm b khoản 1 Điều 21')],'Có điều kiện. Rà lại phạm vi, khối lượng và nguồn; bảo đảm nhiệm vụ trong dự toán được giao. Không chỉ sửa bảng tính mà bỏ quyết định điều chỉnh cần thiết.')
row('A','Phân bổ và giao dự toán cho đơn vị thực hiện → quyết định và thuyết minh phân bổ','–','–','–','C/D: Đơn vị dự toán cấp I; P: đơn vị sử dụng ngân sách',[('104','khoản 1 Điều 21, đặc biệt điểm a, c, đ')],'Trong dự toán được giao, không ảnh hưởng nhiệm vụ chuyên môn khác; kèm thuyết minh công trình, khối lượng, quyết định chủ trương/điều chỉnh. Bố trí cả chi phí chuẩn bị, tư vấn và quyết toán cần thiết.')
row('A','Kiểm tra phân bổ dự toán → kết quả kiểm tra và xử lý kiến nghị','–','–','–','C: Cơ quan tài chính; P: đơn vị dự toán cấp I',[('104','điểm d khoản 1 Điều 21')],'Là kiểm tra phân bổ ngân sách, khác thẩm định thiết kế hoặc dự toán xây dựng. Nếu cần điều chỉnh, hoàn tất trước khi chi theo phần dự toán bị yêu cầu sửa.')
row('A','Giao chủ thể thực hiện và hình thức quản lý → quyết định giao nhiệm vụ/chủ đầu tư','P sau khi được giao','–','P nếu thuê QLDA','C/D: Người có thẩm quyền giao nhiệm vụ/quyết định đầu tư',[('XD','Điều 9; Điều 32'),('217','Điều 6; khoản 3, 6 Điều 44'),('104','điểm a, b khoản 2 Điều 21')],'Tách rõ đơn vị quản lý công trình, đơn vị sử dụng ngân sách, cơ quan chuẩn bị dự án, chủ đầu tư và người quyết định đầu tư. Với nhiệm vụ không hình thành dự án, giao đơn vị thực hiện, không gán tư cách chủ đầu tư xây dựng.')
row('A','Đăng ký tài khoản và người giao dịch Kho bạc → hồ sơ tài khoản, mẫu chữ ký/dấu','P','–','–','C: Đơn vị giao dịch; C: KBNN tiếp nhận, xử lý',[('347','Điều 8')],'Chỉ phát sinh khi chưa đăng ký hoặc có thay đổi. Đơn vị giao dịch phải đúng quyết định giao dự toán/giao chủ đầu tư; không tự lập thêm tài khoản dự án nếu chưa có yêu cầu pháp lý.')

row('B','Lập, thẩm định và phê duyệt chi phí chuẩn bị → dự toán chuẩn bị dự án','C/T/D khi được giao','–','P','C/T/D: Cơ quan chuẩn bị dự án nếu chưa có chủ đầu tư',[('206','khoản 1–3 Điều 11')],'Nhánh có dự án. Cơ quan chuẩn bị dự án hoặc chủ đầu tư tổ chức lập, thẩm định và phê duyệt; cập nhật vào tổng mức đầu tư. Chỉ triển khai trong phạm vi nhiệm vụ, kinh phí hợp pháp được giao.')
row('B','Lựa chọn tư vấn chuẩn bị dự án → kế hoạch, kết quả lựa chọn và hợp đồng tư vấn','C/D nếu đã giao','–','P: tư vấn dự kiến được chọn','C/D: Cơ quan chuẩn bị dự án nếu chưa có chủ đầu tư',[('DT','khoản 5 Điều 37; khoản 2 Điều 40; Điều 78'),('349','khoản 5 Điều 4; Điều 6')],'Thực hiện các bước lựa chọn nhà thầu tại giai đoạn C cho gói khảo sát, thiết kế, thẩm tra cần làm trước. Đây là vòng lựa chọn sớm, không chờ phê duyệt BCKTKT mới chọn đơn vị lập BCKTKT.')
row('B','Lập và phê duyệt nhiệm vụ khảo sát → nhiệm vụ khảo sát','C/D','–','C: tư vấn lập theo giao việc','–',[('XD','Điều 21; Điều 22'),('217','Điều 10; Điều 11')],'Có điều kiện theo nhu cầu thiết kế và hiện trạng. Xác định phạm vi, tiêu chuẩn, khối lượng, thời gian. Có thể dùng số liệu hiện hữu khi được đánh giá đủ tin cậy theo quy định, không tự động khoan khảo sát mọi sửa chữa.')
row('B','Lập, phê duyệt phương án kỹ thuật khảo sát → phương án được duyệt','D/P','–','C: nhà thầu khảo sát','–',[('217','Điều 12')],'Nếu thực hiện khảo sát xây dựng. Kiểm tra phương án đáp ứng nhiệm vụ, điều kiện hiện trường, an toàn và năng lực. Vai trò chủ đầu tư trước quyết định giao được thực hiện bởi cơ quan chuẩn bị dự án trong phạm vi được giao.')
row('B','Thực hiện và quản lý khảo sát → báo cáo kết quả khảo sát, dữ liệu gốc','C: tổ chức quản lý','–','C: khảo sát; P: giám sát khảo sát','–',[('217','Điều 13; Điều 14'),('XD','Điều 37')],'Nhà thầu chịu trách nhiệm kết quả; người quản lý kiểm tra việc tuân thủ nhiệm vụ/phương án. Bổ sung kiểm định hiện trạng nếu cần xác định khả năng chịu lực, phạm vi can thiệp.')
row('B','Nghiệm thu và phê duyệt kết quả khảo sát → biên bản, văn bản phê duyệt','C/D','–','P: khảo sát, thiết kế','–',[('217','Điều 15')],'Kết quả đủ điều kiện mới dùng làm căn cứ thiết kế. Phê duyệt không làm giảm trách nhiệm của nhà thầu khảo sát về độ chính xác.')
row('B','Lập, phê duyệt nhiệm vụ thiết kế → nhiệm vụ thiết kế','C/D','–','C/P: tư vấn thiết kế','–',[('217','Điều 17'),('XD','Điều 19; Điều 20')],'Áp dụng khi cần thiết kế; nêu mục tiêu, quy mô, tiêu chuẩn, yêu cầu công năng/an toàn, nguồn số liệu. BCKTKT dùng thiết kế một bước là bản vẽ thi công theo khoản 1 Điều 19 Luật Xây dựng.')
row('B','Lập hồ sơ kỹ thuật cho nhiệm vụ không lập dự án → phương án, khối lượng và dự toán','C','–','C/P nếu thuê','D: Thủ trưởng/chủ thể có thẩm quyền theo hồ sơ nhiệm vụ',[('104','điểm a khoản 2 Điều 21'),('217','khoản 4 Điều 27'),('207','Điều 34–39')],'Nhánh I nếu đúng công tác bảo trì được miễn lập dự án. Hồ sơ phải đủ xác định công việc, chất lượng, giá và nghiệm thu. Cần xác minh thẩm quyền duyệt dự toán công việc theo phân cấp; không coi đây là miễn thiết kế/an toàn.')
row('B','Lập BCKTKT và thiết kế bản vẽ thi công → bộ BCKTKT, bản vẽ, chỉ dẫn kỹ thuật','C: tổ chức lập','–','C: tư vấn lập, thiết kế','–',[('104','điểm a khoản 2 Điều 21'),('XD','Điều 23; Điều 25'),('217','Điều 23; Điều 30')],'Bắt buộc cho nhánh II; nhánh I nếu hình thành dự án phải đối chiếu Điều 23 Luật Xây dựng. Không cần thêm báo cáo nghiên cứu khả thi theo thủ tục thông thường chỉ vì có hoạt động xây dựng.')
row('B','Xác định dự toán và tổng mức đầu tư → bảng chi phí có căn cứ giá','C: tổ chức kiểm soát','–','C: tư vấn lập dự toán','P: cơ quan công bố giá/định mức',[('206','khoản 6 Điều 5; Điều 6; Điều 12; Điều 22')],'Tính đủ xây dựng, thiết bị, QLDA, tư vấn, chi khác, dự phòng tương ứng. BCKTKT phải có dự toán xây dựng công trình trong tổng mức đầu tư theo khoản 6 Điều 5 NĐ 206; xác định theo Điều 12. Không bỏ dự toán với lý do chỉ thiết kế một bước.')
row('B','Thẩm tra thiết kế, chi phí → báo cáo thẩm tra','C: thuê/giao phù hợp','–','T: tư vấn độc lập đủ năng lực','–',[('XD','khoản 5 Điều 26'),('206','Điều 8'),('217','Điều 31')],'Bắt buộc khi thuộc khoản 5 Điều 26 Luật Xây dựng; ngoài ra theo yêu cầu quản lý hợp pháp. Thẩm tra là đầu vào cho thẩm định, không thay thế cơ quan thẩm định. Không để người lập tự thẩm tra phần việc của mình.')
row('B','Thẩm định phần thiết kế BVTC, tổng mức đầu tư thuộc trách nhiệm chủ đầu tư → kết quả thẩm định','C/T','–','P: lập, thẩm tra','P: cơ quan chủ trì thẩm định',[('217','khoản 7, 8 Điều 31'),('206','khoản 3, 4 Điều 7')],'Theo nhiệm vụ người quyết định đầu tư giao. Khi chủ đầu tư không phải cơ quan chuyên môn trực thuộc, vẫn thực hiện nội dung chi phí thuộc trách nhiệm để cơ quan chủ trì tổng hợp. Không đồng nhất ký kiểm soát nội bộ với phê duyệt BCKTKT.')
row('B','Thẩm định và tổng hợp BCKTKT → báo cáo kết quả thẩm định','P','–','P: giải trình, hoàn thiện','C/T: Cơ quan/tổ chức được người quyết định đầu tư giao chủ trì',[('XD','Điều 26'),('217','khoản 3–8 Điều 31')],'Người quyết định đầu tư giao cơ quan chuyên môn trực thuộc hoặc tổ chức có chuyên môn phù hợp theo khoản 3 Điều 31. Không mặc định BCKTKT dưới 3 tỷ phải chuyển cơ quan chuyên môn về xây dựng thẩm định BCNCKT theo Điều 27 Luật.')
row('B','Phê duyệt BCKTKT và tổng mức đầu tư → quyết định phê duyệt dự án','P','–','P: hoàn thiện','C/D: Người quyết định đầu tư theo thẩm quyền, phân cấp hợp pháp',[('XD','khoản 1 Điều 28'),('217','Điều 39; Mẫu 10 Phụ lục I'),('206','Điều 9')],'Chỉ phê duyệt sau thẩm định và khắc phục yêu cầu. Cần xác minh văn bản giao thẩm quyền phê duyệt BCKTKT của bộ/địa phương; quyền duyệt chủ trương NĐ 104 không tự động là quyền duyệt BCKTKT.')
row('B','Đóng dấu phê duyệt thiết kế BVTC và thống nhất bộ hồ sơ → thiết kế dùng thi công','C/D theo giao của người quyết định đầu tư','–','P','P: người quyết định đầu tư',[('217','khoản 5 Điều 39')],'Với BCKTKT, người quyết định đầu tư giao chủ đầu tư đóng dấu phê duyệt hồ sơ BVTC. Không dựng thêm quy trình thẩm định/phê duyệt thiết kế sau dự án như dự án thiết kế nhiều bước nếu không có bước thiết kế đó.')
row('B','Sàng lọc và thực hiện yêu cầu đất đai, quy hoạch, PCCC, môi trường → hồ sơ chuyên ngành','C','–','C/P: thiết kế, môi trường','C/T/D: Cơ quan đất đai, môi trường, PCCC hoặc chuyên ngành có thẩm quyền',[('XD','Điều 18; Điều 25; điểm đ khoản 3 Điều 26'),('217','khoản 5 Điều 31')],'Có điều kiện theo loại, cấp, công năng và mức can thiệp; làm đồng thời với lập/thẩm định để kịp thời điểm pháp luật yêu cầu. Cần xác minh điều khoản chuyên ngành trực tiếp sau khi có dữ liệu công trình; không mặc định mọi sửa chữa phải có ĐTM hoặc thẩm định PCCC.')
row('B','Xin giấy phép hoặc xác lập căn cứ miễn → giấy phép/phiếu xác định miễn kèm hồ sơ','C','–','P: thiết kế','C/D: Cơ quan cấp phép theo Điều 53 NĐ 217',[('XD','Điều 43; Điều 44'),('217','Điều 51; Điều 53; Điều 54; Điều 61')],'Trước khởi công nếu thuộc diện cấp phép. Miễn phải đối chiếu đúng khoản 2 Điều 43 và điều kiện thực tế; chi thường xuyên, dưới 500 triệu hoặc dưới 3 tỷ không tự tạo miễn giấy phép.')

row('C','Lập danh mục gói thầu và giá gói → dự thảo kế hoạch lựa chọn nhà thầu','C','–','P nếu thuê','P: cơ quan chuẩn bị dự án cho gói làm trước',[('DT','Điều 37; Điều 38; Điều 39'),('206','Điều 13; Điều 15')],'Lặp lại bước C cho từng nhóm tư vấn làm trước và các gói sau phê duyệt. Giá có thuế, dự phòng phù hợp; phân chia theo kỹ thuật, trình tự, không chia nhỏ để đạt hạn mức.')
row('C','Chọn căn cứ hình thức, phương thức và quy trình → thuyết minh lựa chọn','C','–','P','–',[('DT','Điều 21; Điều 23; Điều 24'),('214','Điều 78–80 đã sửa đổi'),('349','khoản 5 Điều 4; Điều 6')],'Hạn mức hiện hành: dự toán mua sắm không hình thành dự án ≤1 tỷ; tư vấn thuộc dự án ≤3 tỷ; phi tư vấn/hàng hóa/xây lắp/hỗn hợp thuộc dự án ≤5 tỷ. Vẫn phải đủ điều kiện. Không chọn hạn mức dự án chỉ vì đã lập BCKTKT; xác định đúng hồ sơ và bản chất gói.')
row('C','Phê duyệt kế hoạch lựa chọn nhà thầu → quyết định KHLCNT','C/D','–','P nếu thuê lập','C/D: Người đứng đầu cơ quan chuẩn bị dự án nếu chưa có chủ đầu tư',[('DT','khoản 2 Điều 40; khoản 2 Điều 41; điểm a khoản 1 Điều 78')],'Chủ đầu tư tổ chức lập, phê duyệt; không mặc định người quyết định đầu tư phê duyệt. Khoản 3 Điều 40 và khoản 3 Điều 41 đã bãi bỏ: không thêm bước thẩm định KHLCNT bắt buộc. Ngoại lệ gói ≤100 triệu xét riêng khoản 4 Điều 80 đã sửa đổi.')
row('C','Đăng tải KHLCNT → bản công khai trên Hệ thống mạng đấu thầu quốc gia','C','–','P nếu được giao','–',[('DT','Điều 7; khoản 4 Điều 8')],'Thực hiện thời hạn công khai của từng thông tin; KHLCNT đăng tải chậm nhất 05 ngày làm việc từ ngày ban hành theo khoản 4 Điều 8 Luật. Giữ bằng chứng thời điểm đăng và nội dung khớp quyết định.')
row('C','Chuẩn bị hồ sơ lựa chọn nhà thầu → HSMT/HSYC hoặc dự thảo hợp đồng','C','–','C/P: tư vấn được thuê, tổ chuyên gia','–',[('DT','Điều 43; Điều 78'),('214','Điều 79; Điều 80'),('349','khoản 3 Điều 6')],'Đấu thầu dùng HSMT theo loại gói; chỉ định thông thường dùng HSYC; chỉ định rút gọn gửi dự thảo hợp đồng. Không yêu cầu đủ cả ba bộ. Gói ≤100 triệu có thể áp dụng khoản 4 Điều 80, vẫn đủ hóa đơn/chứng từ.')
row('C','Thẩm định HSMT/HSYC nếu quy trình yêu cầu → báo cáo thẩm định','C: tổ chức','–','T: tổ thẩm định/tư vấn đủ điều kiện','–',[('DT','khoản 2 Điều 78'),('214','quy trình tương ứng; Điều 79')],'Có điều kiện. Tách lập hồ sơ và thẩm định theo yêu cầu bảo đảm độc lập; không thêm báo cáo thẩm định HSMT cho chỉ định rút gọn vốn không lập HSMT. Cần xác minh điều khoản quy trình cụ thể khi chốt hình thức từng gói.')
row('C','Phê duyệt và phát hành hồ sơ → hồ sơ được duyệt, thông báo hoặc dự thảo đã gửi','C/D','P: nhận hồ sơ','P','–',[('DT','điểm c khoản 1 Điều 78'),('214','Điều 79; Điều 80'),('349','khoản 3 Điều 6')],'Chỉ định rút gọn theo quy định mới gửi dự thảo hợp đồng trên Hệ thống mạng đấu thầu quốc gia, trừ ngoại lệ pháp định. Đấu thầu qua mạng theo phạm vi/lộ trình hiện hành; không tự chuyển sang giấy vì gói nhỏ.')
row('C','Đóng thầu, mở thầu theo hình thức cạnh tranh → biên bản và dữ liệu mở thầu','C','C: nộp hồ sơ đúng hạn','P: tổ chuyên gia/tư vấn','–',[('DT','Điều 43'),('214','quy trình tương ứng tại Chương II–IV hoặc Điều 81')],'Có điều kiện khi áp dụng hình thức cạnh tranh; không phát sinh mở thầu cạnh tranh trong chỉ định. HSMT phải xác định hạn nộp, hiệu lực, bảo đảm dự thầu nếu thuộc diện; tuân thủ thao tác trên Hệ thống. Cần xác minh điều khoản và thời hạn cụ thể của phương thức được chọn trước phát hành.')
row('C','Tiếp nhận, đánh giá hồ sơ và làm rõ → báo cáo đánh giá/biên bản hoàn thiện','C: tổ chức','C: nộp, giải trình','C: tổ chuyên gia/tư vấn đánh giá','–',[('DT','Điều 43; khoản 1a, 1b, 4 Điều 78'),('214','Điều 79; Điều 80')],'Đúng quy trình đã duyệt, không bỏ kiểm tra tư cách, năng lực, tính hợp lý giá. Chỉ định rút gọn đánh giá khả năng thực hiện trên cơ sở dự thảo và hồ sơ nhà thầu, không lập giả hồ sơ dự thầu cạnh tranh.')
row('C','Thương thảo hoặc hoàn thiện điều kiện hợp đồng → biên bản thống nhất','C','C: cùng hoàn thiện','P','–',[('DT','khoản 13 Điều 78'),('214','Điều 79; Điều 80')],'Theo trường hợp, loại gói. Với chỉ định rút gọn, hoàn thiện dự thảo trước phê duyệt kết quả; với đấu thầu thực hiện thương thảo khi pháp luật yêu cầu, không đặt thành bước bắt buộc cho mọi gói.')
row('C','Thẩm định kết quả nếu thuộc diện → báo cáo thẩm định kết quả','C: tổ chức','P nếu cần giải trình','T: tổ thẩm định/tư vấn','–',[('DT','khoản 2 Điều 78'),('214','quy trình tương ứng; Điều 79; Điều 80')],'Có điều kiện theo quy trình; không biến thẩm định thành bước mặc định của chỉ định rút gọn nếu quy định không yêu cầu. Cần xác minh điều khoản trực tiếp của hình thức được chọn trước khi áp dụng.')
row('C','Phê duyệt kết quả lựa chọn → quyết định kết quả','C/D','–','P','–',[('DT','điểm d khoản 1 Điều 78'),('214','Điều 79; khoản 3 Điều 80')],'Người có thẩm quyền phía chủ đầu tư ký; kết quả chỉ rõ nhà thầu, giá, loại hợp đồng, thời gian và nội dung cần thiết. Riêng cơ chế ≤100 triệu thực hiện theo nhánh pháp định được chọn, không tạo đầy đủ quy trình rút gọn khi được miễn.')
row('C','Công khai, thông báo kết quả → dữ liệu đăng tải và thông báo','C','P: nhận thông báo','P','–',[('DT','Điều 7; khoản 4 Điều 8'),('214','Điều 80')],'Đăng đúng phạm vi, thời hạn; kết quả thuộc thông tin quy định tại khoản 4 Điều 8 Luật phải công khai chậm nhất 05 ngày làm việc từ ngày ban hành. Chứng minh việc gửi dự thảo hợp đồng không thay thế công khai kết quả.')
row('C','Kiểm tra bảo đảm và ký hợp đồng → hợp đồng, phụ lục, bảo đảm liên quan','C: ký/giao thầu','C: ký/nhận thầu','P: theo phạm vi hợp đồng tư vấn','P: ngân hàng/tổ chức bảo lãnh nếu có',[('DT','Điều 65–68; khoản 3 Điều 78'),('XD','Điều 81–83'),('210','Điều 4–7; Điều 13')],'Kiểm tra thẩm quyền ký, điều kiện hiệu lực, bảo đảm thực hiện theo trường hợp/ngoại lệ. Quy định rõ phạm vi, giá, nghiệm thu, tạm ứng, thanh toán, bảo hành, quyết toán và thứ tự ưu tiên hồ sơ; tư vấn ký ở vai trò bên nhận thầu của hợp đồng tư vấn.')

row('D','Bàn giao mặt bằng và mốc hiện trạng → biên bản bàn giao','C','C/P: nhận','P: giám sát, thiết kế','P: đơn vị quản lý sử dụng',[('XD','điểm a khoản 1 Điều 48; Điều 59')],'Mặt bằng toàn bộ hoặc từng phần theo tiến độ; ghi tài sản, tuyến điện/nước, khu vực đang hoạt động, mốc, biện pháp cách ly. Không tự bổ sung thu hồi đất/GPMB nếu thực tế không phát sinh.')
row('D','Kiểm tra điều kiện khởi công → danh mục kiểm tra và hồ sơ đủ điều kiện','C','P','P: giám sát','–',[('XD','Điều 48'),('207','Điều 12')],'Mặt bằng, giấy phép nếu phải có, thiết kế được duyệt, hợp đồng và biện pháp an toàn/môi trường theo quy định. Thủ tục chuyên ngành cần có trước khởi công phải hoàn tất, không dùng hợp đồng để thay giấy phép.')
row('D','Thông báo khởi công và thông tin công trường → thông báo, biển công trình','C','P/C: biển và tổ chức công trường','P','P: cơ quan quản lý trật tự xây dựng địa phương',[('XD','Điều 48; Điều 49'),('207','Điều 12; Điều 13')],'Thông báo đúng đối tượng, nội dung và thời điểm thuộc diện phải thông báo. Gửi trước khi khởi công theo khoản 2 Điều 12 NĐ 207, Mẫu Phụ lục V. Quy định này không đặt mốc chung 03 ngày làm việc; không hiểu thông báo là giấy chấp thuận khởi công.')
row('D','Kiểm tra nhân sự, năng lực và hệ thống quản lý → hồ sơ huy động, phân công','C: kiểm tra','C: huy động','P: tư vấn giám sát','–',[('XD','Điều 88–90; Điều 61; Điều 63'),('207','Điều 15; Điều 16')],'Đúng hồ sơ lựa chọn và hợp đồng; thay nhân sự phải đúng điều kiện. Chứng chỉ/chứng nhận chỉ yêu cầu theo loại công việc và đối tượng pháp luật quy định; không suy từ giá gói thầu để miễn toàn bộ năng lực.')
row('D','Lập biện pháp thi công, an toàn, tiến độ → biện pháp và tiến độ được kiểm soát','C: tổ chức xem xét','C: lập và thực hiện','P: giám sát','–',[('XD','Điều 50–52'),('207','Điều 15; Điều 16; Điều 19')],'Trước các công việc tương ứng; kiểm soát làm việc trên cao, điện, phá dỡ và an toàn người đang sử dụng công trình. Nếu có phá dỡ, lập hồ sơ theo Điều 54 Luật và Điều 44 NĐ 207, không gộp mặc nhiên vào khởi công.')
row('D','Mua bảo hiểm bắt buộc khi thuộc diện → hợp đồng/chứng nhận bảo hiểm','C: phần trách nhiệm mình','C: phần trách nhiệm mình','C: bảo hiểm nghề nghiệp khi thuộc diện','P: doanh nghiệp bảo hiểm',[('XD','Điều 10'),('210','Điều 20')],'Có điều kiện theo loại công trình, hoạt động, lao động và trách nhiệm với bên thứ ba. Cần xác minh văn bản bảo hiểm chuyên ngành và đối tượng cụ thể khi có loại/cấp công trình; không tự miễn vì tổng kinh phí thấp.')
row('D','Thực hiện thi công và ghi nhật ký → khối lượng thực tế, nhật ký thi công','P: quản lý','C','P: giám sát','–',[('XD','Điều 50; Điều 61'),('207','Điều 15')],'Thi công theo thiết kế, chỉ dẫn, hợp đồng. Nhật ký thể hiện thời tiết, nhân lực, vật liệu, công việc, vướng mắc và chỉ dẫn; tổ chức hồ sơ liên tục, không hoàn thiện hồi tố bằng số liệu không có thật.')
row('D','Giám sát thi công → nhật ký/biên bản giám sát, báo cáo định kỳ','C: tổ chức','P','C: giám sát đủ năng lực','–',[('XD','Điều 56; Điều 60; Điều 63'),('207','Điều 20')],'Chủ đầu tư tự giám sát khi đủ điều kiện hoặc thuê tư vấn; kiểm tra chất lượng, khối lượng, tiến độ, an toàn. Cột tư vấn là người thực hiện chuyên môn, chủ đầu tư vẫn chịu trách nhiệm tổ chức.')
row('D','Giám sát tác giả → chỉ dẫn thiết kế và báo cáo giám sát tác giả','P','P','C: nhà thầu thiết kế','–',[('XD','Điều 62'),('207','Điều 21')],'Trong phạm vi phần thiết kế đã lập và hợp đồng. Phát hiện thi công sai phải thông báo, kiến nghị; không để chỉ dẫn hiện trường thay thế quyết định phê duyệt điều chỉnh bắt buộc.')
row('D','Kiểm soát vật liệu, cấu kiện, thiết bị → hồ sơ xuất xứ, chất lượng, kiểm tra đầu vào','C: tổ chức','C: cung cấp, tự kiểm tra','C/P: giám sát kiểm tra','P: phòng thí nghiệm/tổ chức đánh giá phù hợp',[('207','Điều 6; Điều 14; khoản 1 Điều 15')],'Chỉ dùng vật liệu phù hợp thiết kế và quy chuẩn/tiêu chuẩn; thí nghiệm theo kế hoạch và chỉ dẫn. CO/CQ hoặc hợp quy chỉ yêu cầu theo loại hàng, hợp đồng/pháp luật, không coi một bộ giấy chung thay kết quả thí nghiệm.')
row('D','Thí nghiệm, quan trắc, kiểm định phát sinh → kết quả chuyên môn','C: tổ chức khi thuộc trách nhiệm','C/P','C/P: tư vấn chuyên môn','C/P: phòng thí nghiệm đủ điều kiện',[('207','Điều 6–8'),('32','Điều 2–4')],'Theo thiết kế, kế hoạch thí nghiệm, dấu hiệu chất lượng hoặc yêu cầu cơ quan có thẩm quyền. Không bắt mọi sửa chữa nhỏ làm kiểm định độc lập; không bỏ thí nghiệm bắt buộc vì giá thấp.')
row('D','Nghiệm thu công việc xây dựng → biên bản nghiệm thu công việc','P: theo tổ chức giám sát','C: phụ trách kỹ thuật','C: người trực tiếp giám sát','–',[('207','Điều 22')],'Không quá 24 giờ từ khi nhận đề nghị nghiệm thu; từ chối phải nêu lý do bằng văn bản (khoản 3). Đúng người ký theo khoản 5; nghiệm thu trước khi che khuất hoặc chuyển công việc tiếp theo.')
row('D','Nghiệm thu bộ phận/giai đoạn khi cần → biên bản nghiệm thu','C','C/P','C/P: giám sát','–',[('207','Điều 23')],'Có điều kiện theo thỏa thuận và yêu cầu chuyển giai đoạn/kết thúc gói. Căn cứ các nghiệm thu công việc và kết quả thử nghiệm; không thêm nghiệm thu giai đoạn trùng lặp nếu không có nhu cầu pháp lý/kỹ thuật.')
row('D','Đo bóc và xác nhận khối lượng, kiểm soát tiến độ → bảng khối lượng, báo cáo tiến độ','C/P','C','C/P: giám sát','–',[('207','Điều 18; Điều 19'),('210','Điều 8; Điều 10')],'Đối chiếu hiện trường, hoàn công và loại hợp đồng. Khối lượng phát sinh chưa có căn cứ hợp lệ không được đưa ngay vào giá trị thanh toán. Theo dõi nguy cơ vượt tổng mức/dự toán và thời gian hợp đồng.')
row('D','Đề xuất và phê duyệt điều chỉnh nhiệm vụ/dự án → quyết định điều chỉnh','C: lập, trình','P','P: tư vấn lập, thẩm tra','C/T/D: Cơ quan thẩm định, người có thẩm quyền tương ứng',[('104','điểm b, đ khoản 1 Điều 21'),('XD','Điều 28'),('217','Điều 40'),('206','Điều 10')],'Chỉ phát sinh khi đủ điều kiện; phân biệt điều chỉnh chủ trương, dự toán ngân sách, dự án/tổng mức. Phải có nguồn hợp pháp, không thi công trước rồi bổ sung chữ ký để hợp thức hóa.')
row('D','Thẩm định, phê duyệt điều chỉnh thiết kế/chi phí → hồ sơ điều chỉnh được duyệt','C/T/D theo thẩm quyền','P','C/T: thiết kế, thẩm tra','T/D: cấp có thẩm quyền nếu thay đổi nội dung thuộc cấp đó',[('XD','Điều 31'),('217','Điều 40; Điều 43'),('206','Điều 10; Điều 18')],'BCKTKT điều chỉnh theo chế độ điều chỉnh dự án khi ảnh hưởng nội dung đã duyệt. Điều 43 áp dụng thiết kế triển khai sau dự án nếu thực tế có bước này. Không áp dụng máy móc thẩm quyền chủ đầu tư cho mọi thay đổi thiết kế BCKTKT.')
row('D','Sửa đổi hợp đồng → phụ lục/văn bản sửa đổi hợp lệ','C: bên giao thầu','C: bên nhận thầu','P','D: người có thẩm quyền nếu trường hợp cần chấp thuận',[('XD','Điều 84'),('210','Điều 22–25'),('DT','Điều 70')],'Sau khi có căn cứ điều chỉnh cần thiết, trong thời gian và điều kiện pháp luật cho phép. Kiểm tra giá, tiến độ, bảo đảm, dự toán/gói thầu và nguồn kinh phí; sửa hợp đồng không tự thay quyết định dự án/ngân sách.')
row('D','Tạm ứng hợp đồng và lập đề nghị Kho bạc → hồ sơ tạm ứng, chứng từ giải ngân','C: kiểm tra, đề nghị','C: đề nghị, bảo đảm nếu phải có','P','C: KBNN kiểm soát, thanh toán',[('104','điểm c khoản 2 Điều 21'),('210','Điều 12'),('347','Điều 6'),('254','Điều 8; Điều 9')],'Tách nhánh theo tổng kinh phí nhiệm vụ, không theo từng hợp đồng: dưới 500 triệu theo NĐ 347; từ 500 triệu theo NĐ 254 được NĐ 104 dẫn chiếu. Chỉ tạm ứng theo hợp đồng, nguồn và bảo lãnh thuộc trường hợp phải có.')
row('D','Nghiệm thu giá trị thanh toán và lập hồ sơ hợp đồng → hồ sơ thanh toán từng đợt','C: kiểm tra/xác nhận','C: lập','P: kiểm tra theo hợp đồng','–',[('210','Điều 28; Điều 29'),('254','khoản 3 Điều 8; Điều 10')],'Thanh toán theo loại giá hợp đồng, giá trị đã nghiệm thu, điều kiện thanh toán. Khấu trừ tạm ứng, giữ bảo hành, thuế theo quy định; không lấy hóa đơn thay nghiệm thu hoặc buộc quyết toán toàn dự án trước mọi thanh toán.')
row('D','Gửi và xử lý thanh toán qua Kho bạc → chứng từ báo Nợ/Có, kết quả kiểm soát','C: đơn vị giao dịch/chủ đầu tư','P','P','C: KBNN nơi giao dịch',[('104','điểm c khoản 2 Điều 21'),('347','khoản 2–5 Điều 6'),('254','Điều 8; Điều 10')],'Nhánh I: NĐ 347, khoản 5 Điều 6 thường 01 ngày làm việc, riêng 25–31/01 và 25–31/12 tối đa 02 ngày. Nhánh II: gửi hồ sơ pháp lý và thanh toán theo NĐ 254 còn hiệu lực; không yêu cầu kế hoạch đầu tư công thay quyết định giao dự toán chi thường xuyên.')
row('D','Thu hồi, thanh toán tạm ứng và đối chiếu lũy kế → sổ theo dõi, xác nhận thu hồi','C','P','P','C/P: KBNN',[('210','Điều 12'),('254','Điều 9'),('347','điểm e khoản 2 Điều 6')],'Gắn thu hồi với các lần thanh toán theo điều khoản áp dụng và hợp đồng; không để tạm ứng treo khi đã đủ khối lượng. Tỷ lệ/mốc thu hồi phải kiểm tra phạm vi áp dụng của từng quy định, không lấy thói quen thanh toán vốn đầu tư áp cho mọi nhiệm vụ.')

row('E','Hoàn thiện hồ sơ chất lượng và bản vẽ hoàn công → hồ sơ hoàn thành','C: tổ chức','C: lập phần thi công','C/P: giám sát, thiết kế','–',[('207','Điều 28; Phụ lục hồ sơ hoàn thành'),('XD','Điều 42')],'Lập hoàn công theo phần việc và trường hợp quy định; đầy đủ nhật ký, thí nghiệm, nghiệm thu, thay đổi thiết kế. Có thể hoàn thiện theo tiến độ, không chờ cuối mới thu thập.')
row('E','Thử nghiệm, chạy thử và hoàn tất điều kiện chuyên ngành → kết quả thử/chấp thuận cần thiết','C','C/P','C/P','C/T: Cơ quan PCCC, môi trường/chuyên ngành nếu thuộc diện',[('207','điểm c, d khoản 1 Điều 24'),('XD','Điều 57')],'Có điều kiện theo công năng, thiết bị, quy định chuyên ngành và thiết kế. Phải hoàn thành điều kiện liên quan trước nghiệm thu/đưa vào sử dụng ở thời điểm pháp luật yêu cầu. Cần xác minh thủ tục chuyên ngành cụ thể theo hồ sơ công trình.')
row('E','Nghiệm thu hoàn thành → biên bản nghiệm thu hạng mục/công trình','C: tổ chức và trực tiếp tham gia','C/P: đúng thành phần','P: giám sát, thiết kế','P: đơn vị sử dụng nếu cần',[('207','Điều 24'),('XD','Điều 57')],'Đủ điều kiện khoản 1 Điều 24; thành phần ký theo khoản 6. Nếu nghiệm thu có điều kiện phải đủ khoản 3, ghi tồn tại và hạn khắc phục; không dùng để bỏ qua lỗi chịu lực, an toàn hoặc chuyên ngành bắt buộc.')
row('E','Kiểm tra công tác nghiệm thu của Nhà nước khi thuộc diện → thông báo kết quả','C: đề nghị, giải trình','P','P','C: Cơ quan có thẩm quyền theo Điều 26 NĐ 207',[('207','Điều 25–27'),('XD','khoản 4 Điều 57')],'Chỉ khi thuộc Điều 25; không mặc định mọi công trình có ngân sách phải kiểm tra. Kiểm tra diễn ra trong thi công và khi hoàn thành; lập lịch từ giai đoạn D. Hồ sơ/chấp thuận là điều kiện đưa vào sử dụng nếu thuộc diện.')
row('E','Bàn giao và đưa vào khai thác → biên bản bàn giao, hồ sơ vận hành','C','P','P','C: Chủ sở hữu/đơn vị quản lý, sử dụng tiếp nhận',[('XD','Điều 58'),('207','Điều 29; Điều 30')],'Chỉ khi đủ Điều 29; bàn giao hồ sơ kỹ thuật, hoàn công, hướng dẫn sử dụng, danh mục thiết bị/tài sản, chìa khóa và nội dung bảo hành. Không chờ hết bảo hành mới bàn giao.')
row('E','Bàn giao bảo hành và quy trình bảo trì → cam kết/bảo đảm bảo hành, quy trình được duyệt','C/D: tổ chức, phê duyệt theo trách nhiệm','C: bảo hành, hồ sơ thiết bị','C/P: thiết kế lập quy trình','C/P: Chủ sở hữu/người quản lý sử dụng',[('207','Điều 32–35'),('XD','Điều 64; Điều 65')],'Với công trình ngân sách xây mới/cải tạo/nâng cấp: cấp còn lại bảo hành ít nhất 12 tháng, cấp đặc biệt/I ít nhất 24 tháng; tiền bảo hành tối thiểu tương ứng 5%/3% theo Điều 32. Trường hợp sửa chữa bảo trì đối chiếu riêng Điều 38 và hợp đồng.')

row('F','Đối chiếu hoàn thành hợp đồng và công nợ → bảng đối chiếu A–B','C','C','P','P: KBNN đối chiếu tiền đã chi',[('210','Điều 30'),('193','Điều 6; điểm d khoản 1 Điều 7')],'Xác định khối lượng hợp lệ, phát sinh được duyệt, tổng đã trả, tạm ứng chưa thu, thuế, giữ bảo hành và còn phải trả. Mẫu quyết toán A–B của NĐ 193 khác Mẫu báo cáo tổng hợp 01/QTDA của TT 73.')
row('F','Lập và xác nhận quyết toán từng hợp đồng → hồ sơ quyết toán hợp đồng','C: kiểm tra/xác nhận','C: lập với hợp đồng thi công','C: lập với hợp đồng tư vấn; P: kiểm tra khi được thuê','–',[('XD','Điều 87'),('210','Điều 30'),('193','điểm d khoản 1 Điều 7; Mẫu 01/QTDA')],'Áp dụng cả hai nhánh có hợp đồng. Thời hạn 60 ngày, tối đa 120 ngày cho hợp đồng lớn/phức tạp theo khoản 3 Điều 30 trong phạm vi quy định tại đoạn 2 khoản 1; đối chiếu điểm c khoản 1 Điều 17 Luật Xây dựng cho dự án chi thường xuyên.')
row('F','Thanh toán cuối và giải quyết tiền giữ lại → hồ sơ thanh toán, chứng từ','C','C/P','P','C: KBNN',[('210','Điều 28–30'),('254','Điều 8; Điều 10'),('347','Điều 6')],'Thu hồi hết tạm ứng theo chế độ; tiền bảo hành chỉ hoàn trả theo điều kiện bảo hành hoặc thay bảo lãnh được chấp nhận. Thanh toán cuối hợp đồng khác phê duyệt quyết toán dự án hoàn thành.')
row('F','Tổng hợp quyết toán ngân sách hằng năm → báo cáo quyết toán chi thường xuyên','P: cung cấp số liệu','P','P','C: Đơn vị sử dụng ngân sách; T/D: cấp xét duyệt/thẩm định ngân sách',[('104','Điều 22'),('NS','Cần xác minh điều khoản, mẫu và thời hạn quyết toán năm theo cấp ngân sách, loại đơn vị')],'Bắt buộc cả hai nhánh, kể cả chưa kết thúc toàn nhiệm vụ. Số liệu khớp Kho bạc và sổ kế toán; không chờ quyết toán công trình hoàn thành mới ghi báo cáo ngân sách năm.')
row('F','Xác định kiểm toán và lập hồ sơ quyết toán hoàn thành → hồ sơ theo NĐ 193','C','P: cung cấp quyết toán hợp đồng','P; C: kiểm toán nếu thuê','P: cơ quan chủ trì thẩm tra',[('104','khoản 2 Điều 22'),('193','Điều 6; Điều 7; Điều 9; Điều 21'),('73','khoản 1 Điều 4')],'Bắt buộc nhánh II; nhánh I nếu có dự án thuộc Điều 1 NĐ 193 thì đối chiếu riêng, không miễn chỉ do dưới 500 triệu. Dự án nhóm C: lập hồ sơ tối đa 04 tháng từ bàn giao hoặc mốc dừng theo Điều 21. Không bắt buộc kiểm toán độc lập chỉ vì kinh phí ngân sách.')
row('F','Nộp, kiểm tra và tiếp nhận hồ sơ quyết toán → phiếu giao nhận, yêu cầu bổ sung','C','P nếu bổ sung','P','C: Cơ quan chủ trì thẩm tra; P: người phê duyệt',[('193','Điều 7'),('73','khoản 6 Điều 4; Mẫu 12/QTDA')],'Gửi 01 bộ người phê duyệt và 01 bộ cơ quan thẩm tra; nếu người phê duyệt đồng thời là thủ trưởng cơ quan chủ trì thẩm tra chỉ gửi 01 bộ theo Điều 7. Ghi chính xác ngày đủ hồ sơ để tính thời hạn.')
row('F','Thẩm tra quyết toán hoàn thành → báo cáo thẩm tra và dự thảo quyết định','P: giải trình','P','P: giải trình theo phần việc','C/T: Cơ quan chủ trì theo Điều 8 NĐ 193',[('193','Điều 8; Điều 10–19; Điều 21')],'Nhóm C: tối đa 02 tháng từ nhận đủ hồ sơ đến trình phê duyệt. Chủ thể tỉnh thường là Sở Tài chính theo điểm a khoản 2 Điều 8; trường hợp phân cấp/ủy quyền đối chiếu hồ sơ cụ thể. Kiểm toán không thay thẩm tra.')
row('F','Phê duyệt quyết toán hoàn thành → quyết định và số liệu tài sản/công nợ','P','–','–','C/D: Người quyết định đầu tư hoặc chủ thể được phân cấp/ủy quyền hợp pháp',[('193','điểm b, d khoản 1 Điều 8; Điều 19; Điều 21'),('73','khoản 4 Điều 4; Mẫu 10/QTDA')],'Nhóm C: tối đa 07 ngày từ khi người phê duyệt nhận đủ hồ sơ trình duyệt. Không coi thủ trưởng đơn vị sử dụng ngân sách tự có quyền duyệt nếu không là chủ thể được pháp luật giao.')
row('F','Xử lý sau quyết toán và kinh phí dư → thu hồi/nộp trả, thanh toán công nợ','C','C/P: hoàn trả/thanh toán','P','C/P: đơn vị kế toán, KBNN, cơ quan tài chính',[('193','Điều 28'),('347','điểm g, h khoản 2 Điều 6'),('NS','Điều 66')],'Theo quyết định duyệt, thu hồi chi sai, xử lý dư dự toán/tạm ứng, thanh toán khoản còn hợp pháp. Chuyển nguồn chỉ khi đủ điều kiện, không mặc định kéo dài dự toán vì công trình chưa xong.')
row('F','Ghi nhận, điều chỉnh tài sản công → biên bản và sổ tài sản cập nhật','C/P','P','P','C: Đơn vị tiếp nhận/quản lý tài sản và kế toán',[('193','Điều 16; Điều 28'),('207','Điều 30'),('104','khoản 1 Điều 20')],'Phân biệt chi sửa chữa hạch toán chi phí với nâng cấp làm tăng nguyên giá/tài sản mới theo chế độ kế toán và tài sản công. Cần xác minh điều khoản ghi tăng, thời hạn kê khai theo loại tài sản và đơn vị; không ghi tăng toàn bộ giá trị mọi sửa chữa.')
row('F','Thanh lý hợp đồng khi đủ điều kiện → biên bản/văn bản thanh lý','C','C: hợp đồng thi công','C: hợp đồng tư vấn','–',[('XD','Điều 87'),('210','Điều 31')],'Khi hoàn thành nghĩa vụ hoặc chấm dứt theo quy định; không ép thanh lý khi nghĩa vụ bảo hành còn chưa được xử lý theo thỏa thuận. Thời hạn 45/90 ngày trong phạm vi khoản 3 Điều 31; ghi rõ nghĩa vụ tiếp tục còn hiệu lực nếu có.')
row('F','Lập mục lục, bàn giao và lưu trữ → hồ sơ hoàn thành, danh mục lưu trữ','C','C: bàn giao phần mình','C: bàn giao phần mình','C/P: đơn vị lưu trữ, đơn vị quản lý sử dụng',[('XD','Điều 42'),('207','Điều 28'),('DT','khoản 4–6 Điều 9; khoản 8 Điều 78')],'Tách hồ sơ gửi KBNN với bộ chứng từ gốc phải lưu. Lưu bản có chữ ký hợp lệ và phiên bản điện tử có thể truy vết. Hồ sơ lựa chọn nhà thầu tối thiểu 05 năm từ quyết toán hợp đồng theo khoản 6 Điều 9 Luật Đấu thầu, trừ nhóm hồ sơ luật quy định khác; hồ sơ hủy thầu theo khoản 4. Cần xác minh thời hạn xây dựng/kế toán riêng.')
row('F','Theo dõi bảo hành, sửa lỗi và xác nhận kết thúc → biên bản bảo hành, hoàn trả bảo đảm','C: kiểm tra/xác nhận','C: sửa lỗi, báo cáo','P','C/P: chủ sở hữu/đơn vị sử dụng',[('207','Điều 32; khoản 1–5 Điều 33')],'Tiếp tục sau thanh toán/quyết toán. Khi hết hạn, kiểm tra thực hiện, xác nhận bằng văn bản và hoàn trả tiền/giải tỏa bảo lãnh nếu đạt yêu cầu. Lưu hồ sơ khiếm khuyết, thông báo, sửa chữa và nghiệm thu bảo hành.')

doc=Document()
doc.settings.odd_and_even_pages_header_footer=False
sec=doc.sections[0]; sec.page_width=Cm(29.7);sec.page_height=Cm(21)
sec.top_margin=sec.bottom_margin=Cm(1.7);sec.left_margin=sec.right_margin=Cm(1.5)
sec.header_distance=Cm(.65);sec.footer_distance=Cm(.65)
for name in ['Normal','Title','Heading 1','Heading 2','Heading 3']:
 st=doc.styles[name];st.font.name='Times New Roman';st.font.color.rgb=RGBColor(0,0,0)
 st.element.get_or_add_rPr().rFonts.set(qn('w:eastAsia'),'Times New Roman')
doc.styles['Normal'].font.size=Pt(12)
doc.styles['Normal'].paragraph_format.space_after=Pt(6)
doc.styles['Normal'].paragraph_format.line_spacing=1.08
doc.styles['Title'].font.size=Pt(19);doc.styles['Title'].font.bold=True
doc.styles['Heading 1'].font.size=Pt(15);doc.styles['Heading 2'].font.size=Pt(13)
def para(t='',style=None): return doc.add_paragraph(t,style)
def heading(t):doc.add_heading(t,level=1)
def link(p,text,url):
 h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(url,RT.HYPERLINK,is_external=True))
 r=OxmlElement('w:r');rp=OxmlElement('w:rPr');c=OxmlElement('w:color');c.set(qn('w:val'),'174A70');rp.append(c)
 r.append(rp);t=OxmlElement('w:t');t.text=text;r.append(t);h.append(r);p._p.append(h)
def cite(p,refs):
 for j,(k,clause) in enumerate(refs):
  if j:p.add_run('\n')
  link(p,S[k][0],S[k][1]);p.add_run(', '+clause+'.')
def body(t,refs=None):
 p=para(t)
 if refs:p.add_run(' ');cite(p,refs)
 return p

para('Quy trình thực hiện nhiệm vụ và dự án xây dựng sử dụng kinh phí chi thường xuyên dưới 3 tỷ đồng','Title')
para('Tài liệu hướng dẫn thực hiện và kiểm soát hồ sơ pháp lý tại ngày 28 tháng 10 năm 2026')
body('Phạm vi: cơ quan nhà nước và đơn vị sử dụng ngân sách, chưa xác định bộ quản lý hoặc địa phương. Quy trình gồm 5 phần; bảng công việc có đúng 8 cột và đánh số liên tục. Cần hoàn thiện thông tin công trình và phân cấp trước khi dùng để ký quyết định cụ thể. Không gắn tên hay thẩm quyền của Trường Cao đẳng Kon Tum vào quy trình chung này.')

heading('Phần 1 Phân tích pháp lý sơ bộ')
doc.add_heading('1 Cơ chế và căn cứ trực tiếp',level=2)
body('Điều 40 Luật Ngân sách nhà nước cho phép bố trí nguồn chi thường xuyên cho những nhiệm vụ luật quy định; việc có hoạt động xây dựng không tự biến nguồn này thành vốn đầu tư công. Với sửa chữa, cải tạo, nâng cấp, mở rộng, xây mới hạng mục trong dự án đã đầu tư xây dựng, cơ chế trực tiếp là Điều 20–22 Nghị định 104/2026/NĐ-CP. Mức dưới 3 tỷ đồng là phạm vi tài liệu này, không phải một ngưỡng miễn thủ tục chung.',[('NS','Điều 40'),('104','Điều 20–22')])
body('Cần phân biệt nguồn kinh phí với cách quản lý xây dựng. Điểm c khoản 1 Điều 17 Luật Xây dựng 135/2025/QH15 quy định dự án sử dụng chi thường xuyên từ NSNN, vốn NSNN khác ngoài phạm vi pháp luật đầu tư công thực hiện theo quy định đối với dự án đầu tư công tại chính Luật Xây dựng. Khoản 5 Điều 5 Nghị định 217/2026 cũng dẫn chiếu tương ứng trong nghị định này. Vì vậy áp dụng các quy định xây dựng được dẫn chiếu có căn cứ, nhưng không tự bổ sung quyết định chủ trương đầu tư công, kế hoạch vốn đầu tư công hay thủ tục khác của Luật Đầu tư công.',[('XD','điểm c khoản 1 Điều 17'),('217','khoản 5 Điều 5')])
doc.add_heading('2 Hai nhánh theo tổng kinh phí nhiệm vụ',level=2)
body('Nhánh I — dưới 500 triệu đồng: thủ trưởng đơn vị quản lý công trình tổ chức thực hiện theo điểm a khoản 2 Điều 21 Nghị định 104; thanh toán qua Kho bạc theo Điều 6 Nghị định 347/2025 theo điểm c cùng khoản; tổng hợp quyết toán ngân sách năm theo khoản 1 Điều 22. Đây là ngưỡng của dự toán kinh phí thực hiện nhiệm vụ, không phải giá từng gói thầu hoặc từng hợp đồng.',[('104','điểm a, c khoản 2 Điều 21; khoản 1 Điều 22'),('347','Điều 6')])
body('Dưới 500 triệu không đồng nghĩa được miễn mọi BCKTKT. Nếu chỉ là công tác bảo trì trên cơ sở thiết kế công trình hiện hữu hoặc không cần lập thiết kế, khoản 4 Điều 27 Nghị định 217 quy định không phải lập dự án. Nếu công việc hình thành dự án xây dựng, phải đối chiếu khoản 1, 2 Điều 23 Luật Xây dựng và Điều 27 Nghị định 217; dự án nhỏ thông thường lập BCKTKT. Không dùng sự im lặng của Nghị định 104 về BCKTKT ở nhánh nhỏ để miễn nghĩa vụ mà Luật Xây dựng trực tiếp đặt ra. Hồ sơ phải ghi nhận rõ kết quả phân loại. Nếu bản chất công việc chưa rõ, xin ý kiến cơ quan xây dựng trước khi bỏ hồ sơ dự án.',[('XD','Điều 23'),('217','khoản 2, 4 Điều 27')])
body('Nhánh II — từ đúng 500 triệu đồng đến dưới 3 tỷ đồng: lập, trình phê duyệt BCKTKT theo điểm a khoản 2 Điều 21 Nghị định 104; thanh toán qua Kho bạc theo Nghị định 254/2025 do điểm c cùng khoản dẫn chiếu. Ngoài quyết toán ngân sách năm, phải quyết toán dự án hoàn thành sử dụng chi thường xuyên theo khoản 2 Điều 22. Từ 01/7/2026, quyết toán hoàn thành thực hiện theo Nghị định 193/2026 và mẫu tại Thông tư 73/2026. Không bỏ bước quyết toán hoàn thành vì nguồn tiền là chi thường xuyên.',[('104','điểm a, c khoản 2 Điều 21; khoản 2 Điều 22'),('193','Điều 1; Điều 31'),('73','Điều 1; Điều 4; Điều 5')])
body('Nếu nhiệm vụ dưới 500 triệu vẫn hình thành dự án thuộc phạm vi Điều 1 Nghị định 193, phải rà thêm chế độ quyết toán dự án theo nghị định này; khoản 1 Điều 22 Nghị định 104 không được dùng như một miễn trừ chung cho mọi dự án. Riêng giao thoa giữa công tác bảo trì được miễn lập dự án tại khoản 4 Điều 27 Nghị định 217 và nhiệm vụ từ 500 triệu thuộc yêu cầu BCKTKT tại Nghị định 104: phương án thận trọng của bảng là thực hiện BCKTKT theo quy định trực tiếp về nguồn chi; chỉ bỏ bước khi có căn cứ chuyên biệt hoặc ý kiến cơ quan có thẩm quyền xác nhận cho hồ sơ thực tế.')
doc.add_heading('3 Thẩm quyền và hồ sơ xây dựng',level=2)
body('Phê duyệt chủ trương và dự kiến chi phí theo khoản 2 Điều 20 Nghị định 104: Bộ trưởng/thủ trưởng cơ quan trung ương hoặc UBND tỉnh quyết định hay quy định phân cấp trong phạm vi quản lý. Giao dự toán do đơn vị dự toán cấp I thực hiện theo khoản 1 Điều 21. BCKTKT do người quyết định đầu tư có thẩm quyền phê duyệt theo khoản 1 Điều 28 Luật Xây dựng và Điều 39 Nghị định 217. Những thẩm quyền này cần được xác lập riêng; không suy ra người duyệt BCKTKT từ người duyệt chủ trương hay từ người ký giao dự toán.',[('104','khoản 2 Điều 20; khoản 1 Điều 21'),('XD','khoản 1 Điều 28'),('217','Điều 39')])
body('BCKTKT gồm thuyết minh và thiết kế bản vẽ thi công, thiết kế công nghệ nếu có; thiết kế một bước. Cơ quan chủ trì thẩm định theo Điều 31 Nghị định 217 tổng hợp nội dung thuộc trách nhiệm của mình và phần chủ đầu tư thực hiện theo khoản 7; không tự chuyển toàn bộ BCKTKT sang thủ tục thẩm định Báo cáo nghiên cứu khả thi của cơ quan chuyên môn về xây dựng. Khoản 6 Điều 5 Nghị định 206 quy định tổng mức đầu tư của BCKTKT gồm dự toán xây dựng công trình theo Điều 12, chi phí bồi thường, hỗ trợ, tái định cư nếu có và các chi phí liên quan tính chung cho dự án. Vì vậy phải lập đủ dự toán thành phần trong BCKTKT; không suy từ thiết kế một bước để miễn lập dự toán.',[('XD','khoản 1 Điều 19; Điều 25; Điều 26'),('217','Điều 30; Điều 31'),('206','khoản 6 Điều 5; Điều 6; Điều 7; Điều 12')])
body('Danh mục cần xác minh trước khi áp dụng: cấp ngân sách, đơn vị cấp I, quyết định giao quản lý tài sản; quyết định phân cấp phê duyệt chủ trương/BCKTKT/quyết toán; người được giao làm chủ đầu tư; công năng, loại/cấp, mức can thiệp kết cấu; tình trạng đất, quy hoạch, PCCC, môi trường; thời điểm phê duyệt và phát hành hồ sơ cũ nếu chuyển tiếp. Chưa có địa phương nên không áp một quyết định của Quảng Ngãi hoặc bộ cụ thể làm căn cứ chung.')
doc.add_heading('4 Lựa chọn nhà thầu theo quy định đã sửa đổi',level=2)
body('Tại ngày chốt, khoản 4 Điều 78 Nghị định 214/2025 đã được khoản 5 Điều 4 Nghị định 349/2026 sửa đổi: gói thuộc dự toán mua sắm không hình thành dự án không quá 1 tỷ đồng; tư vấn thuộc dự án không quá 3 tỷ; phi tư vấn, hàng hóa, xây lắp, hỗn hợp thuộc dự án không quá 5 tỷ. Không dùng các hạn mức cũ 500 triệu, 800 triệu, 2 tỷ. Hạn mức 5 tỷ được kiểm tra trên văn bản gốc và đối chiếu trả lời Bộ Tài chính ngày 24/10/2026; một số tin tóm tắt nêu 3 tỷ cho xây lắp không được dùng thay điều khoản gốc.',[('349','khoản 5 Điều 4'),('MOF','hướng dẫn áp dụng khoản 4 Điều 78')])
body('Dưới 3 tỷ chưa đủ để kết luận mọi gói được chỉ định thầu. Phải phân loại gói thuộc dự án hay dự toán mua sắm không hình thành dự án, đủ điều kiện khoản 2 Điều 79 và chọn quy trình Điều 80 đã sửa đổi. Nếu đúng gói xây lắp thuộc dự án thì trong phạm vi giá của tài liệu này có thể đáp ứng điều kiện về hạn mức 5 tỷ, nhưng vẫn còn điều kiện pháp lý và trách nhiệm lựa chọn. Gói không thuộc dự án trên 1 tỷ không tự được chỉ định theo hạn mức. Không chia nhỏ nhiệm vụ để né ngưỡng.',[('DT','Điều 16; Điều 23'),('214','Điều 78–80'),('349','Điều 4; Điều 6')])
body('Với gói hoặc nội dung mua sắm không quá 100 triệu, khoản 4 Điều 80 đã sửa đổi cho phép thủ trưởng quyết định mua sắm, bảo đảm tiết kiệm, hiệu quả và hóa đơn/chứng từ đầy đủ, không phải đáp ứng điều kiện khoản 2 Điều 79 hay quy trình khoản 3 Điều 80, hoặc được chọn quy trình chỉ định rút gọn. Cơ chế này chỉ giản lược lựa chọn nhà thầu theo đúng phạm vi; không miễn phê duyệt nhiệm vụ, ngân sách, chất lượng, thanh toán và tài sản.',[('349','khoản 4 Điều 6')])
body('Chủ đầu tư lập và phê duyệt KHLCNT theo khoản 2 Điều 40, khoản 2 Điều 41 Luật Đấu thầu đã sửa đổi. Nếu chưa xác định chủ đầu tư cho gói cần làm trước, người đứng đầu đơn vị chuẩn bị dự án thực hiện theo khoản 2 Điều 40. Không có bước thẩm định KHLCNT bắt buộc theo khoản 3 cũ đã bãi bỏ. HSMT/HSYC và kết quả lựa chọn được phê duyệt, thẩm định nếu có theo Điều 78 và quy trình tương ứng.',[('DT','Điều 40; Điều 41; Điều 78')])
doc.add_heading('5 Thanh toán và ba lớp quyết toán',level=2)
body('Quyết toán hợp đồng là xác nhận giá trị công việc giữa bên giao thầu và nhận thầu theo Điều 87 Luật Xây dựng, Điều 30 Nghị định 210. Quyết toán ngân sách năm là tổng hợp thu, chi của đơn vị theo Điều 22 Nghị định 104 và pháp luật ngân sách/kế toán. Quyết toán dự án hoàn thành là xác định toàn bộ chi phí, tài sản và công nợ, thẩm tra và phê duyệt theo Nghị định 193 khi thuộc diện. Ba kết quả này không thay thế nhau.',[('210','Điều 30'),('104','Điều 22'),('193','Điều 1; Điều 6–8')])
body('Nghị định 193 áp dụng trực tiếp cho dự án sử dụng chi thường xuyên, không phải áp dụng bằng suy luận từ vốn đầu tư công. Nghị định này có hiệu lực 01/7/2026 và bãi bỏ các Điều 30–47 cùng nội dung liên quan của Nghị định 254 về quyết toán hoàn thành. Thông tư 73 thay chế độ mẫu quyết toán hoàn thành tương ứng; không dùng Thông tư 27/2025 hoặc phần mẫu đã bãi bỏ của Thông tư 91/2025 cho hồ sơ mới. Mẫu 01/QTDA trong phụ lục Nghị định 193 là quyết toán A–B; Mẫu 01/QTDA của Thông tư 73 là báo cáo tổng hợp, phải ghi cả văn bản ban hành để tránh nhầm.',[('193','Điều 7; khoản 5 Điều 31'),('73','Điều 3–5')])
body('Đối với nhánh I, Nghị định 347 là thủ tục Kho bạc hiện hành, thời hạn xử lý tại khoản 5 Điều 6 là 01 ngày làm việc, ngoại lệ các ngày 25–31/01 và 25–31/12 là 02 ngày làm việc từ khi có hồ sơ hợp lệ. Hồ sơ gửi Kho bạc phải phân biệt với chứng từ gốc đơn vị phải lưu. Thông tư 17/2024 và Thông tư 89/2021 bị bãi bỏ theo Thông tư 16/2026; không yêu cầu cam kết chi theo thông tư đã bãi bỏ cho hồ sơ mới.',[('347','Điều 6'),('16','Điều 1–3')])
doc.add_heading('6 Hiệu lực và chuyển tiếp',level=2)
body('Hồ sơ mới tại ngày 28/10/2026 dùng văn bản hiện hành nêu ở Phần 5. Hồ sơ có trước phải lập phiếu mốc thời gian để đối chiếu Điều 29 Nghị định 104; Điều 95 Luật Xây dựng; điều khoản chuyển tiếp Nghị định 217, Điều 36 Nghị định 206, Điều 53 Nghị định 207, Điều 33 Nghị định 210; điều khoản chuyển tiếp Nghị định 349; Điều 29 Nghị định 193 và khoản 5 Điều 5 Thông tư 73. Không áp một ngày chuyển tiếp chung cho cả nhiệm vụ, đấu thầu, hợp đồng và quyết toán.')

heading('Phần 2 Bảng quy trình thực hiện chi tiết')
body('Ký hiệu: C — chủ trì; P — phối hợp; T — thẩm tra/thẩm định; D — phê duyệt/quyết định; – — không tham gia trực tiếp. Ký hiệu kết hợp thể hiện các phần trách nhiệm khác nhau trong cùng sản phẩm. Cột Chủ đầu tư chỉ dành cho chủ thể đã được giao đúng tư cách; trước thời điểm đó hoặc với nhiệm vụ không hình thành dự án, chủ thể thực hiện ghi rõ tại Cơ quan khác. Không có nghĩa đơn vị sử dụng ngân sách tự động là chủ đầu tư.')
body('Bắt buộc áp dụng cho nhánh được nêu, trừ dòng ghi “có điều kiện”. Các tài liệu nội bộ như phiếu phân loại, bảng kiểm được đề xuất để kiểm soát, không tự tạo thêm thủ tục hành chính. Giai đoạn C được thực hiện lặp cho gói chuẩn bị tại B và gói triển khai sau phê duyệt. Khởi tạo công tác nghiệm thu nhà nước từ D nếu thuộc diện; bước nghiệm thu hoàn thành nằm tại E.')

T=doc.add_table(rows=1,cols=8);T.alignment=WD_TABLE_ALIGNMENT.CENTER;T.autofit=False
widths=[1.0,4.6,1.55,1.4,1.55,3.0,5.2,8.4] # total 26.7 cm
headers=['STT','Công việc/Sản phẩm','Chủ đầu tư','Nhà thầu','Tư vấn','Cơ quan khác','Căn cứ/nguồn','Ghi chú']
for c,w,h in zip(T.rows[0].cells,widths,headers):c.width=Cm(w);c.text=h
repeat=OxmlElement('w:tblHeader');T.rows[0]._tr.get_or_add_trPr().append(repeat)
def shade(cell,color):
 sh=OxmlElement('w:shd');sh.set(qn('w:fill'),color);cell._tc.get_or_add_tcPr().append(sh)
phases={'A':'Chuẩn bị nhiệm vụ và kinh phí','B':'Chuẩn bị hồ sơ xây dựng và phê duyệt','C':'Lựa chọn nhà thầu','D':'Tổ chức thi công và thanh toán trong quá trình thực hiện','E':'Nghiệm thu và bàn giao','F':'Quyết toán và kết thúc'}
last=None
for n,data in enumerate(R,1):
 ph,work,own,ct,cons,other,refs,note=data
 if ph!=last:
  cells=T.add_row().cells;cells[0].text='';cells[1].text=f'GIAI ĐOẠN {ph}\n{phases[ph]}'
  for c in cells:shade(c,'DCE6EE')
  for c in cells:
   for p in c.paragraphs:p.paragraph_format.keep_with_next=True
  for r in cells[1].paragraphs[0].runs:r.bold=True
  # Preserve eight distinct cells even on stage divider rows.
  last=ph
 cells=T.add_row().cells
 values=[str(n),work,own,ct,cons,other,'',note]
 for c,w,v in zip(cells,widths,values):c.width=Cm(w);c.text=v
 cite(cells[6].paragraphs[0],refs)
 if n%2==0:
  for c in cells:shade(c,'F5F7F9')

for ri,r in enumerate(T.rows):
 trp=r._tr.get_or_add_trPr();trp.append(OxmlElement('w:cantSplit'))
 for ci,c in enumerate(r.cells):
  c.width=Cm(widths[ci])
  c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
  tcpr=c._tc.get_or_add_tcPr();mar=OxmlElement('w:tcMar')
  for edge,val in [('top',70),('bottom',70),('left',70),('right',70)]:
   el=OxmlElement('w:'+edge);el.set(qn('w:w'),str(val));el.set(qn('w:type'),'dxa');mar.append(el)
  tcpr.append(mar)
  for p in c.paragraphs:
   p.paragraph_format.space_after=Pt(1);p.paragraph_format.line_spacing=1.02
   if ci in [0,2,3,4]:p.alignment=WD_ALIGN_PARAGRAPH.CENTER
   for run in p.runs:run.font.size=Pt(10.5)
  # Set font on hyperlink runs too.
  for rr in c._tc.xpath('.//w:r'):
   rp=rr.find(qn('w:rPr'))
   if rp is None:rp=OxmlElement('w:rPr');rr.insert(0,rp)
   sz=OxmlElement('w:sz');sz.set(qn('w:val'),'21');rp.append(sz)
   ft=OxmlElement('w:rFonts');ft.set(qn('w:ascii'),'Times New Roman');ft.set(qn('w:hAnsi'),'Times New Roman');rp.append(ft)
  if ri==0:
   shade(c,'24465C')
   for run in c.paragraphs[0].runs:run.bold=True;run.font.color.rgb=RGBColor(255,255,255)
borders=OxmlElement('w:tblBorders')
for edge in ['top','left','bottom','right','insideH','insideV']:
 e=OxmlElement('w:'+edge);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');borders.append(e)
T._tbl.tblPr.append(borders)
for grid,w in zip(T._tbl.tblGrid.gridCol_lst,widths):grid.set(qn('w:w'),str(round(w*567)))
tw=T._tbl.tblPr.find(qn('w:tblW'));tw.set(qn('w:type'),'dxa');tw.set(qn('w:w'),str(round(sum(widths)*567)))

heading('Phần 3 Danh mục hồ sơ cần lưu trữ')
groups=[
('1 Nhiệm vụ và nguồn kinh phí','Bắt buộc: hồ sơ hiện trạng; thuyết minh nhu cầu và phạm vi; quyết định chủ trương/dự kiến chi phí; hồ sơ dự toán năm; giao/điều chỉnh dự toán; kiểm tra phân bổ; giao đơn vị thực hiện. Có điều kiện: quyết định điều chỉnh chủ trương, bổ sung kinh phí và hồ sơ phân cấp/ủy quyền áp dụng.','104','Điều 20–22'),
('2 Tư cách chủ thể và quản lý','Bắt buộc theo nhánh: giao cơ quan chuẩn bị, giao chủ đầu tư nếu có dự án; hình thức quản lý; nhân sự và phân công; tài khoản Kho bạc, chữ ký số/mẫu dấu đang có hiệu lực. Có điều kiện: hợp đồng thuê QLDA, quyết định giao thay/chuyển chủ đầu tư, biên bản bàn giao dự án.','217','Điều 6; Điều 44–48'),
('3 Khảo sát và thiết kế','Bắt buộc nếu phải lập BCKTKT: nhiệm vụ thiết kế, khảo sát cần thiết, báo cáo kết quả và phê duyệt khảo sát, BCKTKT, BVTC, thuyết minh chi phí, thẩm định, phê duyệt, hồ sơ đóng dấu. Có điều kiện: phương án khảo sát, kiểm định hiện trạng, thẩm tra, điều chỉnh. Nhiệm vụ bảo trì không lập dự án lưu hồ sơ phương án, khối lượng và dự toán phù hợp.','217','Điều 10–17; Điều 23; Điều 27; Điều 30–31; Điều 39'),
('4 Hồ sơ chuyên ngành','Có điều kiện: giấy tờ đất/quy hoạch, giấy phép hoặc căn cứ miễn; thẩm định/kiểm tra nghiệm thu PCCC; môi trường; hồ sơ di sản, đấu nối và chuyên ngành khác. Hồ sơ sàng lọc phải ghi lý do không thuộc diện; không ghi chung “đã đầy đủ” khi chưa xác định công năng và loại công trình.','XD','Điều 18; Điều 43–44'),
('5 Lựa chọn nhà thầu','Bắt buộc theo quy trình đã chọn: KHLCNT và quyết định; đăng tải; HSMT/HSYC/dự thảo hợp đồng tương ứng; hồ sơ dự thầu/đề xuất hoặc năng lực; đánh giá, làm rõ, thương thảo/hoàn thiện; thẩm định nếu có; quyết định và công khai kết quả. Cơ chế ≤100 triệu lưu căn cứ, quyết định theo trách nhiệm và hóa đơn/chứng từ; không tạo bộ hồ sơ giả theo quy trình không thực hiện.','DT','Điều 7–8; Điều 37–41; Điều 78'),
('6 Hợp đồng và bảo đảm','Bắt buộc: hợp đồng có hiệu lực, phụ lục, phân công đại diện, điều kiện nghiệm thu/thanh toán/quyết toán/bảo hành. Có điều kiện: bảo đảm thực hiện, bảo lãnh tạm ứng, bảo hiểm, văn bản điều chỉnh/chấm dứt, hồ sơ thầu phụ và tranh chấp.','210','Điều 4–13; Điều 19–31'),
('7 Thi công và quản lý chất lượng','Bắt buộc theo phạm vi thi công: bàn giao mặt bằng, điều kiện/thông báo khởi công thuộc diện; biện pháp, tiến độ, nhân sự; nhật ký; vật liệu/thiết bị; kết quả thí nghiệm; giám sát; nghiệm thu công việc, khối lượng. Có điều kiện: nghiệm thu giai đoạn, quan trắc/kiểm định, xử lý sự cố, phát sinh và quyết định điều chỉnh.','207','Điều 12–24'),
('8 Hoàn thành và khai thác','Bắt buộc: hồ sơ hoàn thành tương ứng, bản vẽ hoàn công thuộc diện; nghiệm thu hoàn thành; bàn giao; hướng dẫn sử dụng, quy trình bảo trì; bảo hành. Có điều kiện: chạy thử, hồ sơ nghiệm thu chuyên ngành, thông báo chấp thuận nghiệm thu của cơ quan nhà nước, nghiệm thu có điều kiện và khắc phục tồn tại.','207','Điều 24–35'),
('9 Tạm ứng và thanh toán','Bắt buộc: chứng từ gốc, hóa đơn, hồ sơ nghiệm thu giá trị, đề nghị chi và kết quả Kho bạc, đối chiếu lũy kế, tạm ứng/thu hồi. Nhánh I theo NĐ 347; nhánh II lưu hồ sơ theo NĐ 254 được dẫn chiếu. Bộ hồ sơ giữ tại đơn vị có thể nhiều hơn hồ sơ gửi KBNN; không suy giảm nghĩa vụ kế toán theo số tài liệu KBNN yêu cầu.','104','điểm c khoản 2 Điều 21'),
('10 Quyết toán năm và quyết toán hoàn thành','Cả hai nhánh: báo cáo quyết toán ngân sách năm, đối chiếu, thông báo xét duyệt/thẩm định áp dụng. Nhánh II: tờ trình, mẫu 01–07/QTDA của TT 73, hồ sơ pháp lý, quyết toán A–B theo NĐ 193, nghiệm thu/bàn giao, thẩm tra, quyết định mẫu 10/QTDA, tài sản/công nợ; báo cáo kiểm toán, thanh tra nếu có. Có điều kiện: dự án dừng dùng mẫu và hồ sơ riêng.','193','Điều 6–8; Điều 19; Điều 21'),
('11 Tài sản và sau quyết toán','Bắt buộc theo phát sinh: bàn giao, ghi nhận/điều chỉnh tài sản, công nợ, xử lý kinh phí dư và thu hồi; thanh lý khi đủ điều kiện; thông báo hư hỏng, sửa chữa và xác nhận hết bảo hành, giải tỏa bảo đảm. Kèm mục lục hồ sơ, nơi lưu và người nhận để truy vết.','207','Điều 28; Điều 30; Điều 32–33')]
for title,txt,k,cl in groups:doc.add_heading(title,level=2);body(txt,[(k,cl)])
body('Lưu ý về thời hạn bảo quản: không đặt một thời hạn chung cho toàn bộ hồ sơ. Cần xác minh chế độ lưu trữ xây dựng, đấu thầu, kế toán và tài sản công hiện hành theo từng nhóm; ghi thời hạn và bản gốc/bản điện tử trong danh mục lưu của đơn vị. Mục này là cấu trúc kiểm soát hồ sơ, không tự ban hành bảng thời hạn bảo quản.')

heading('Phần 4 Các điểm cần kiểm soát rủi ro')
risks=[
('Sai nguồn hoặc sai đối tượng chi','Kiểm tra công trình thuộc dự án đã đầu tư, nguồn dự toán và tiêu chuẩn/định mức trước duyệt chủ trương. Khi ngoài phạm vi Điều 40/Điều 20 NĐ 104, dừng áp quy trình này để xác định cơ chế nguồn khác.','104','Điều 1; Điều 20'),
('Chọn sai nhánh 500 triệu','Dùng tổng dự toán kinh phí nhiệm vụ hợp pháp, không riêng giá xây lắp, hợp đồng hoặc giá trị chi của một năm. Khi điều chỉnh vượt mốc, rà lại hồ sơ BCKTKT, Kho bạc và quyết toán, không chia nhỏ để giữ nhánh đơn giản.','104','khoản 2 Điều 21; Điều 22'),
('Bỏ BCKTKT hoặc yêu cầu BCKTKT quá mức','Tách bảo trì không phải lập dự án theo Điều 27.4 NĐ 217 khỏi dự án thuộc Điều 23 Luật Xây dựng. Nhánh từ 500 triệu tuân thủ yêu cầu trực tiếp NĐ 104; lập văn bản hỏi cơ quan có thẩm quyền nếu có giao thoa chưa rõ trong hồ sơ thực tế.','217','Điều 27'),
('Ký sai thẩm quyền','Lập danh sách căn cứ giao/phân cấp cho từng quyết định: chủ trương, giao dự toán, BCKTKT, KHLCNT, kết quả, quyết toán. Chưa có văn bản phân cấp thì không điền chức danh dự đoán vào mẫu ký.','104','khoản 2 Điều 20'),
('Dùng hạn mức cũ hoặc chỉ định mặc định','Đối chiếu điều khoản gốc đã sửa đổi 1/3/5 tỷ; kiểm tra dự án hay dự toán mua sắm và điều kiện khoản 2 Điều 79. Lưu lập luận chọn hình thức; bảo đảm cạnh tranh, tiết kiệm và không chia nhỏ.','349','khoản 5 Điều 4; Điều 6'),
('Chờ BCKTKT rồi mới chọn đơn vị lập BCKTKT','Tổ chức vòng lựa chọn gói chuẩn bị trước theo Điều 37, Điều 40 Luật Đấu thầu và dự toán chuẩn bị hợp pháp. Tránh tư vấn đã thực hiện rồi mới ký kết quả lựa chọn/hợp đồng.','DT','khoản 5 Điều 37; khoản 2 Điều 40'),
('Phê duyệt, thẩm tra và thẩm định bị đánh đồng','Tách báo cáo thẩm tra của tư vấn, kết quả thẩm định phần chủ đầu tư, thẩm định tổng hợp và quyết định phê duyệt. Không thêm thẩm định KHLCNT theo khoản đã bãi bỏ, không lấy đóng dấu thiết kế thay quyết định BCKTKT.','217','Điều 31; Điều 39'),
('Thi công hoặc phát sinh trước hồ sơ hợp lệ','Dùng bảng kiểm điều kiện khởi công; nghiệm thu trước che khuất; phê duyệt thay đổi thuộc diện trước khi triển khai. Theo dõi riêng biến động nhiệm vụ, ngân sách, thiết kế, dự toán và hợp đồng.','XD','Điều 28; Điều 31; Điều 48; Điều 84'),
('Thanh toán sai nhánh hoặc dùng thông tư đã bãi bỏ','NĐ 104 trực tiếp tách NĐ 347 và NĐ 254 theo mốc 500 triệu. Không áp TT 17/2024/TT-BTC, TT 89/2021/TT-BTC cho hồ sơ mới sau bãi bỏ; giữ chứng từ gốc đầy đủ ở đơn vị.','104','điểm c khoản 2 Điều 21'),
('Nghiệm thu không đủ điều kiện và thiếu trách nhiệm','Kiểm tra đúng người ký, hồ sơ chất lượng và điều kiện chuyên ngành; xác định công trình thuộc Điều 25 NĐ 207 ngay đầu thi công. Kiểm tra nhà nước không thay trách nhiệm nghiệm thu của chủ đầu tư/nhà thầu.','207','Điều 22–27'),
('Bỏ quyết toán hoàn thành hoặc vẫn dùng chương cũ NĐ 254','Nhánh II có hai báo cáo ngân sách năm và hoàn thành; hồ sơ mới dùng NĐ 193, TT 73. Đặt lịch nhóm C 04 tháng lập, 02 tháng thẩm tra, 07 ngày phê duyệt từ đúng mốc luật; không đợi hết bảo hành mới lập quyết toán.','193','Điều 21; Điều 31'),
('Nhầm mẫu hoặc tự buộc kiểm toán','Ghi rõ Mẫu 01/QTDA theo NĐ 193 là A–B, còn theo TT 73 là báo cáo tổng hợp. Kiểm toán độc lập không mặc định bắt buộc cho nhóm C; nếu thuê phải có phạm vi/chi phí hợp pháp, không coi kiểm toán thay thẩm tra.','193','Điều 7; Điều 9'),
('Sai tài sản và bỏ theo dõi sau bàn giao','Hạch toán theo bản chất sửa chữa/nâng cấp/tài sản mới; đối chiếu quyết toán và bàn giao. Lập sổ bảo hành, giữ bảo đảm theo đúng chế độ; chỉ giải tỏa khi có xác nhận hoàn thành nghĩa vụ.','207','Điều 30; Điều 32–33'),
('Chuyển tiếp bị áp một cách đồng loạt','Lập phiếu mốc của chủ trương, dự án, phát hành hồ sơ đấu thầu, ký hợp đồng, nộp quyết toán. Áp đúng điều khoản chuyển tiếp từng lĩnh vực; bản dự thảo hoặc tin tóm tắt không thay văn bản đã ban hành.','193','Điều 29')]
for i,(title,txt,k,cl) in enumerate(risks,1):body(f'{i}. {title}. {txt}',[(k,cl)])

heading('Phần 5 Danh mục văn bản pháp luật sử dụng')
body('Ngày chốt kiểm tra 28/10/2026. “Còn hiệu lực” dưới đây là tình trạng áp dụng đối với các nội dung viện dẫn đã kiểm tra trên nguồn chính thức; văn bản đã sửa đổi được sử dụng theo nội dung sửa đổi. Văn bản hợp nhất phục vụ đọc, không có ngày hiệu lực độc lập và không thay văn bản gốc. Danh mục không khẳng định mọi thủ tục chuyên ngành đều phát sinh cho mọi công trình.')
laws=[
('NS','Luật Ngân sách nhà nước 89/2025/QH15 ngày 25/6/2025, áp dụng từ năm ngân sách 2026; đọc cùng các sửa đổi có liên quan, trong đó Luật 145/2025/QH15. Căn cứ dùng: Điều 40; quản lý chi, xử lý cuối năm và quyết toán. Chưa xác minh đầy đủ mẫu báo cáo ngân sách năm riêng của từng loại đơn vị.'),
('104','Ban hành và có hiệu lực 31/3/2026, thay NĐ 98/2025. Căn cứ chính: Điều 20, 21, 22; Mẫu 02; Điều 29 về hiệu lực và chuyển tiếp. Trực tiếp điều chỉnh chủ trương, dự toán, thanh toán và quyết toán nhiệm vụ đang xét.'),
('XD','Ban hành 10/12/2025, hiệu lực chung 01/7/2026; một số nội dung có hiệu lực 01/01/2026 theo Điều 94. Căn cứ: Điều 9, 17–28, 32, 42–65, 73–90; Điều 95 chuyển tiếp. Không dùng Luật 2014 làm căn cứ mặc định cho hồ sơ mới.'),
('217','Ban hành 19/6/2026, hiệu lực 01/7/2026, được sửa đổi liên quan bởi NĐ 347/2026 ngày 08/9/2026. Căn cứ: Điều 5–6; 10–17; 23; 27; 30–31; 39–48; 51–54; 61. Đọc cùng bản hợp nhất 91/2026/VBHN-NĐ-BXD tháng 9/2026.'),
('91','Bản hợp nhất đọc NĐ 217 với sửa đổi bởi NĐ 347/2026; dùng để đối chiếu toàn văn hiện hành, không coi là một nghị định mới. Một số dòng thể thức của bản hợp nhất có lỗi kỹ thuật; số hiệu, ngày và hiệu lực căn cứ theo văn bản gốc.'),
('206','Ban hành 15/6/2026, hiệu lực 01/7/2026. Điều 2 áp dụng trực tiếp dự án chi thường xuyên. Điều 5–18, 22, 25–31 về chi phí, Điều 36 chuyển tiếp. Khoản 2 Điều 1 không điều chỉnh giá hợp đồng, thanh toán/quyết toán hợp đồng và thanh toán/quyết toán vốn.'),
('207','Ban hành 15/6/2026, hiệu lực 01/7/2026. Điều 12–24 thi công/nghiệm thu; 25–30 kiểm tra, hồ sơ và bàn giao; 32–39 bảo hành, bảo trì; Điều 53 chuyển tiếp. Là quy định hiện hành cho hồ sơ mới thay việc mặc định dùng NĐ 06/2021.'),
('32','Ban hành 22/6/2026, áp dụng theo điều khoản hiệu lực 01/7/2026; hướng dẫn NĐ 207. Điều 2–4 về kế hoạch thí nghiệm, quan trắc và kiểm định; chỉ phát sinh theo đối tượng cụ thể.'),
('210','Ban hành 15/6/2026, hiệu lực 01/7/2026. Điều 4–13 ký kết, giá, tạm ứng, bảo đảm; 20–31 bảo hiểm, sửa đổi, thanh toán, quyết toán và thanh lý; Điều 33 chuyển tiếp. Phân biệt quy định áp dụng chung với khoản quy định riêng cho dự án đầu tư công/PPP, kết hợp dẫn chiếu Điều 17 Luật Xây dựng.'),
('DT','Luật Đấu thầu 22/2023/QH15, hiệu lực gốc 01/01/2024, đã sửa bởi Luật 57/2024, 90/2025, 116/2025, 133/2025, 142/2025; đọc VBHN 74/VBHN-VPQH ngày 25/3/2026. Các sửa đổi có hiệu lực đến ngày chốt được áp dụng. Căn cứ: Điều 7–8, 16, 21, 23–24, 37–43, 65–70, 78.'),
('214','NĐ 214/2025 có hiệu lực 04/8/2025; đọc cùng các sửa đổi NĐ 165/2026, 170/2026 và 349/2026. Nguồn liên kết là VBHN 36/2026/VBHN-NĐ-BTC ngày 23/9/2026. Căn cứ: Điều 78–80 và quy trình tương ứng hình thức được chọn. Các sửa đổi y tế/dược không mặc nhiên áp cho xây lắp thông thường.'),
('349','Ban hành và có hiệu lực 09/9/2026. Khoản 5 Điều 4 sửa hạn mức Điều 78.4 NĐ 214; Điều 6 sửa Điều 80 về quy trình và cơ chế không quá 100 triệu; kiểm tra điều khoản thi hành/chuyển tiếp khi có hồ sơ đã phát hành trước ngày hiệu lực.'),
('347','Ban hành 29/12/2025, hiệu lực 01/01/2026. Điều 6 thủ tục chi thường xuyên, Điều 8 đăng ký tài khoản. Áp nhánh dưới 500 triệu theo dẫn chiếu tại NĐ 104; không nhầm với NĐ 347/2026 về lĩnh vực khác.'),
('254','Ban hành và có hiệu lực 26/9/2025. Phần thanh toán còn hiệu lực được NĐ 104 Điều 21.2.c dẫn chiếu cho nhánh từ 500 triệu; dùng Điều 8–10 về hồ sơ, tạm ứng và thanh toán. Từ 01/7/2026, phần quyết toán hoàn thành tại Điều 30–47 và nội dung liên quan bị bãi bỏ theo NĐ 193 Điều 31, không dùng như chế độ đầy đủ hiện hành.'),
('193','Ban hành 01/6/2026, hiệu lực 01/7/2026. Điều 1 áp dụng trực tiếp cả dự án sử dụng chi thường xuyên; Điều 6–9, 10–21, 25–28 về hồ sơ, chủ thể, thẩm tra, thời hạn và trách nhiệm. Điều 29 chuyển tiếp; Điều 31 bãi bỏ phần quyết toán cũ. Còn hiệu lực đối với nội dung sử dụng.'),
('73','Ban hành 25/6/2026, hiệu lực 01/7/2026. Điều 3–4: mẫu 01–07/QTDA cho báo cáo dự án hoàn thành, mẫu 10 quyết định, mẫu 12 giao nhận. Điều 5 bãi bỏ TT 27/2025 và các nội dung tương ứng của TT 91/2025; hồ sơ đã nộp trước hiệu lực không phải lập lại mẫu theo khoản 5.'),
('16','Ban hành, hiệu lực 05/3/2026. Điều 1 bãi bỏ TT 89/2021 và TT 17/2024; Điều 3 chuyển tiếp chỉ với chi thường xuyên năm 2025 đến hết 31/01/2026. Dùng để loại căn cứ cũ, không dùng như thông tư hướng dẫn kiểm soát chi mới.'),
]
for i,(k,t) in enumerate(laws,1):
 p=para();p.add_run(f'{i}. ').bold=True;link(p,S[k][0],S[k][1]);p.add_run('. '+t)
doc.add_heading('Nguồn đối chiếu và những điểm cần xác minh tại đơn vị',level=2)
body('Đã bổ sung tra cứu Exa theo yêu cầu qua các hướng: hạn mức và quy trình lựa chọn nhà thầu; hai nhánh kinh phí/BCKTKT/Kho bạc; thẩm quyền xây dựng; quản lý chất lượng; chế độ quyết toán và văn bản hợp nhất. Kết quả tìm kiếm được dùng phát hiện nguồn; nội dung pháp lý của bảng dựa vào văn bản chính thức. Các bản toàn văn chính thức đã đọc và trích lưu trong hồ sơ nghiên cứu của lần lập này.')
for k in ['MOF','MOF2']:
 p=para();link(p,S[k][0],S[k][1]);p.add_run(' — nguồn giải thích để đối chiếu, không phải văn bản quy phạm pháp luật và không thay điều khoản gốc.')
body('Cần xác minh theo hồ sơ cụ thể: (1) văn bản phân cấp/ủy quyền của bộ hoặc địa phương; (2) căn cứ chuyên ngành PCCC, môi trường, đất đai, di sản, bảo hiểm; (3) điều kiện năng lực cụ thể của từng nhà thầu; (4) quy trình, mẫu hồ sơ đấu thầu điện tử tại ngày tổ chức từng gói; (5) chế độ kế toán, ghi nhận và kê khai tài sản, lưu trữ và mẫu quyết toán ngân sách năm của đơn vị. Những chỗ này được nêu rõ trong cột Ghi chú; chưa đủ dữ kiện để ghi số điều chuyên ngành áp dụng riêng. Các thiếu hụt này không được diễn giải thành miễn thủ tục.')
body('Tự kiểm trước xuất: đã tách nguồn chi với tư cách dự án; tách hai nhánh 500 triệu; phân biệt chủ trương, giao dự toán, BCKTKT, KHLCNT và kết quả lựa chọn; kiểm tra hạn mức mới 1/3/5 tỷ; tách thẩm tra/thẩm định/phê duyệt; bố trí vòng chọn tư vấn trước; có điều kiện khởi công, chất lượng, nghiệm thu, Kho bạc, ba lớp quyết toán, tài sản và bảo hành; giữ đủ 8 cột và số thứ tự liên tục. Tài liệu chưa thực hiện rà soát theo KTC-Ra-Soat-897; đây không phải hồ sơ trình ký của một đơn vị cụ thể.')

